UPCampOwner:
/*▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣
** Procedure 설명	: 마을의 소유권처리를 위해 진영전쟁 우승팀의 정보를 얻는다
** Argument설명		: 없음
** Return Type		: CampOwnerData 정보
** 수정 사항
** Date				: 2010-06-10
** Programmer		: 황태윤
** Changes			: 신규작성
**▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣▣*/
CREATE  PROC [dbo].[UPCampOwner] @CampType TINYINT
AS
	SET NOCOUNT ON

	DECLARE @Campidx SMALLINT,@LPoint TINYINT,@DPoint TINYINT,@CPoint TINYINT,@Clanidx SMALLINT,@Tax TINYINT
	DECLARE @ClanName VARCHAR(17),@Captain VARCHAR(20),@MarkFlag TINYINT,@MarkOp1 BIGINT,@MarkOp2 BIGINT,@MarkOp3 BIGINT,@MarkOp4 BIGINT,@MarkOp5 BIGINT,
			@CUserIdx INT, @CCharIdx TINYINT

	-- 소유진영 정보 확인
	SELECT @Campidx=OwnerCampIndex,@LPoint=LCampWinPoint,@DPoint=DCampWinPoint,@CPoint=CCampWinPoint,@Clanidx=MvpClanIndex,@Tax=TaxRate
	FROM dbo.CampOwnerData WITH (READUNCOMMITTED) WHERE CampType=@CampType

	-- 점령 클랜이 있다면 클랜정보 확인
	IF @Clanidx>=0 AND @Campidx>=0
	BEGIN
		SELECT @ClanName=Cname,@Captain=Captain,@CUserIdx=Capuserindex,@CCharIdx=CapCharidx,@MarkFlag=MarkFlag,@MarkOp1=Markidx,@MarkOp2=MarkColor,@MarkOp3=MarkBorder,@MarkOp4=MarkBdColor,@MarkOp5=MarkBgColor
		FROM dbo.ClanData WITH (READUNCOMMITTED) WHERE Clanidx=@Clanidx
	END
	ELSE
	BEGIN
		SET @ClanName = '';
		SET @Captain = '';
		SET @CUserIdx = -1;
		SET @CCharIdx = 0;
		SET @MarkFlag = 0;
		SET @MarkOp1 = 0;
		SET @MarkOp2 = 0;
		SET @MarkOp3 = 0;
		SET @MarkOp4 = 0;
		SET @MarkOp5 = 0;
	END
	
	SELECT @Campidx AS OwnerCampIndex,@Tax AS TaxRate,@LPoint AS LCampWinPoint,@DPoint AS DCampWinPoint,@CPoint AS CCampWinPoint,
		@Clanidx AS MvpClanIndex,@ClanName AS Cname,@CUserIdx AS CapUserIndex,@CCharIdx AS CapCharIndex,@Captain AS Captain,
		@MarkFlag AS MarkFlag,@MarkOp1 AS Markidx,@MarkOp2 AS MarkColor,@MarkOp3 AS MarkBorder,@MarkOp4 AS MarkBdColor,@MarkOp5 AS MarkBgColor
	
	SET NOCOUNT OFF

UPFameRatingHolderUp:
CREATE PROCEDURE dbo.UPFameRatingHolderUp
    @TitleId  TINYINT,
    @CharId   INT,
    @CharIdx  TINYINT,
    @Value    BIGINT    = 0,
    @CharName CHAR(21) = N''
AS
BEGIN
    SET NOCOUNT ON;
    /* no SET XACT_ABORT here either - it would stick to the connection.
       The transaction is guarded by TRY/CATCH instead. */

    DECLARE @oCharId  INT       = 0,
            @oCharIdx TINYINT   = 0,
            @oName    CHAR(21) = N'',
            @oValue   BIGINT    = 0,
            @oGranted TINYINT   = 0,
            @Changed  TINYINT   = 0,
            @found    INT       = 0;

    BEGIN TRY
    BEGIN TRANSACTION;

    SELECT @oCharId  = h.CharId,   @oCharIdx = h.CharIdx,
           @oName    = h.CharName, @oValue   = h.Value,
           @oGranted = h.Granted
    FROM dbo.FameRatingHolder h WITH (UPDLOCK, HOLDLOCK)
    WHERE h.TitleId = @TitleId;
    SET @found = @@ROWCOUNT;

    IF @found = 0
    BEGIN
        INSERT dbo.FameRatingHolder (TitleId) VALUES (@TitleId);
        SELECT @oCharId = 0, @oCharIdx = 0, @oName = N'', @oValue = 0, @oGranted = 0;
    END

    IF @oCharId <> @CharId OR @oCharIdx <> @CharIdx
    BEGIN
        SET @Changed = 1;

        IF @oCharId <> 0 AND @oGranted <> 0
            INSERT dbo.FameRatingRevoke (TitleId, CharId, CharIdx, CharName)
            VALUES (@TitleId, @oCharId, @oCharIdx, @oName);

        UPDATE dbo.FameRatingHolder
           SET CharId      = @CharId,
               CharIdx     = @CharIdx,
               CharName    = @CharName,
               Value       = @Value,
               Granted     = 0,
               GrantedDate = GETDATE(),
               PrevCharId  = @oCharId,
               PrevCharIdx = @oCharIdx,
               PrevName    = @oName,
               PrevValue   = @oValue,
               ChangedDate = GETDATE(),
               UpdateDate  = GETDATE()
         WHERE TitleId = @TitleId;
    END
    ELSE
        UPDATE dbo.FameRatingHolder
           SET CharName   = @CharName,
               Value      = @Value,
               UpdateDate = GETDATE()
         WHERE TitleId = @TitleId;

    COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        /* the caller still gets exactly one row: "nothing changed, nobody to strip" */
        SELECT @Changed = 0, @oCharId = 0, @oCharIdx = 0, @oValue = 0,
               @oGranted = 0, @oName = N'';
    END CATCH

    SELECT CAST(@TitleId  AS TINYINT)   AS TitleId,
           CAST(@Changed  AS TINYINT)   AS IsChanged,
           CAST(@oCharIdx AS TINYINT)   AS PrevCharIdx,
           CAST(@oGranted AS TINYINT)   AS PrevGranted,
           CAST(@oCharId  AS INT)       AS PrevCharId,
           CAST(@oValue   AS BIGINT)    AS PrevValue,
           CAST(@oName    AS CHAR(21)) AS PrevName;
END
